using Crm.Mediator;

namespace Crm.Testing.Outbox;

/// <summary>
/// What <see cref="OutboxConformanceTests"/> needs from one module. Each module's test project implements it over its own
/// DbContext, outbox, relay and inbox (generated by make module-new), so Crm.Testing needs no EF Core (ADR-009, ADR-015).
/// </summary>
public interface IOutboxHarness
{
    /// <summary>The test database, for checks the suite makes in SQL.</summary>
    string ConnectionString { get; }

    /// <summary>The module's SQL schema.</summary>
    string Schema { get; }

    /// <summary>Deletes every row in the module's tables, keeping the schema.</summary>
    Task ResetAsync();

    /// <summary>
    /// In one transaction: saves a change to one of the module's entities and writes one integration event through the
    /// module's outbox; then commits or rolls back. Returns the event's message ID.
    /// </summary>
    Task<Guid> SaveChangeWithEventAsync(bool commit, CancellationToken cancellationToken);

    /// <summary>How many of the entities <see cref="SaveChangeWithEventAsync"/> writes exist.</summary>
    Task<int> CountChangedEntitiesAsync(CancellationToken cancellationToken);

    /// <summary>
    /// One pass of a new relay instance (its own DbContext, as after a restart) publishing through
    /// <paramref name="publisher"/>. Returns how many messages it published.
    /// </summary>
    Task<int> RunRelayOnceAsync(IEventPublisher publisher, CancellationToken cancellationToken);

    /// <summary>
    /// Delivers <paramref name="envelope"/> to a subscriber in this module that guards with the module's inbox and then
    /// saves one entity change. With <paramref name="fail"/> the subscriber throws after its change, before saving.
    /// </summary>
    Task DeliverToInboxSubscriberAsync(MessageEnvelope envelope, bool fail, CancellationToken cancellationToken);

    /// <summary>How many changes the inbox subscriber saved for <paramref name="messageId"/>.</summary>
    Task<int> CountInboxSubscriberChangesAsync(Guid messageId, CancellationToken cancellationToken);

    /// <summary>The outbox row for <paramref name="messageId"/>, or null.</summary>
    Task<OutboxMessageState?> FindOutboxMessageAsync(Guid messageId, CancellationToken cancellationToken);
}

/// <summary>An outbox row as the conformance suite sees it.</summary>
public sealed record OutboxMessageState(
    Guid MessageId, int Attempts, DateTimeOffset NextAttemptAt, DateTimeOffset? ProcessedAt, DateTimeOffset? DeadLetteredAt);
